import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { join } from "node:path";
import { test } from "node:test";

/**
 * DESIGN.md → design-tokens 生成管线一致性（specs/gen-ui-visualize.md
 * 「DESIGN.md → design-tokens 生成管线」验收场景 10）。
 *
 * 管线纪律：DESIGN.md 是单一来源，references/design-tokens.md 是编译产物
 * （@generated 头指回脚本与源文档）；手动运行不进构建，漂移防护全靠本测试——
 * 改了 DESIGN.md token 节而忘重跑生成器时，`pnpm test` 必须红。
 */

const cliRoot = fileURLToPath(new URL("..", import.meta.url));
const scriptPath = join(cliRoot, "scripts", "generate-visualize-design-tokens.mjs");

const {
  DESIGN_MD_PATH,
  OUTPUT_PATH,
  GENERATED_HEADER,
  renderDesignTokensReference,
} = await import("../scripts/generate-visualize-design-tokens.mjs");

const designMarkdown = await readFile(DESIGN_MD_PATH, "utf8");
const committed = await readFile(OUTPUT_PATH, "utf8");

test("产物与 DESIGN.md 重生成逐字节一致（漂移即红）", () => {
  assert.equal(committed, renderDesignTokensReference(designMarkdown));
});

test("--check 对当前树退出码 0", () => {
  execFileSync(process.execPath, [scriptPath, "--check"], { cwd: cliRoot, stdio: "pipe" });
});

test("--check 对漂移输入拒绝：DESIGN.md 变异后重渲染不再等于产物", () => {
  // 模拟「改了源没重跑生成器」：把 xl 档公式 +4px 改成 +6px。
  const mutated = designMarkdown.replace(
    "| `text-ui-xl`      | `--ui-font-size + 4px` |    18px |",
    "| `text-ui-xl`      | `--ui-font-size + 6px` |    20px |",
  );
  assert.notEqual(mutated, designMarkdown, "变异锚点行没找到，测试需随 DESIGN.md 更新");
  assert.notEqual(renderDesignTokensReference(mutated), committed);
});

test("DESIGN.md 标题重排必须炸出来，不静默产出缺节参考", () => {
  const truncated = designMarkdown.replace("### Common size baselines", "### Control baselines");
  assert.throws(() => renderDesignTokensReference(truncated), /heading not found/);
});

test("@generated 头纪律：首行指回脚本与源文档，声明勿手改", () => {
  const [firstLine] = committed.split("\n");
  assert.equal(firstLine, GENERATED_HEADER);
  assert.match(firstLine, /@generated by apps\/acode-cli\/scripts\/generate-visualize-design-tokens\.mjs/);
  assert.match(firstLine, /from DESIGN\.md/);
  assert.match(firstLine, /Do not edit by hand/);
});

test("产物内容面：字号表/间距节奏/圆角阶梯/色角色组在场，且无 CJK（技能内容纪律）", () => {
  for (const expected of [
    "text-ui-xl",
    "Base spacing unit is `4px`",
    "### Container hierarchy",
    "rounded-lg",
    "- **Core semantic colors**: `--color-brand`",
    "--color-workflow-trace",
  ]) {
    assert.ok(committed.includes(expected), `产物缺少：${expected}`);
  }
  // Color Palette 的长散文被压缩为 token 名列表——源文档的使用规则句不得整体搬运进产物。
  assert.ok(!committed.includes("Never use as a full-page background"));
  assert.ok(!/[\u4e00-\u9fff\u3040-\u30ff]/.test(committed), "产物含 CJK");
});
